# Status board

The operations team's board: the health of each service, the signed-in account's notifications, and a "Sync now" button that refreshes every service's state from the upstream status service.

```bash
npm start   # http://127.0.0.1:4173 (PORT changes it)
npm test
```

- `server.mjs` serves the page and a small JSON API. Every start loads `data/`, so a restart resets the board. `data/upstream.json` is what the upstream status service answers during a sync; `{ "error": "timeout" }` means it does not answer for that service.
- `public/src/health.js` is the health panel, `notifications.js` the notifications panel, `sync.js` the sync button, `retry.js` the retry helper and `api.js` the client.
- Product requirements are in `docs/REQUIREMENTS.md`.

API:

| Request | Answer |
| --- | --- |
| `GET /api/account` | the signed-in account |
| `GET /api/services` | every service and its state |
| `GET /api/notifications` | the signed-in account's notifications |
| `POST /api/sync` | `{ syncedAt, updated: [ids], failed: [ids] }` |

Playwright and its Chromium are installed for driving the page in scripts.
const STATES = {
  operational: 'Operational',
  degraded: 'Degraded',
  outage: 'Outage',
}

export const stateLabel = (state) => STATES[state] ?? state

/** "09:15" in the viewer's time zone. */
export const clock = (iso) =>
  new Date(iso).toLocaleTimeString('en-GB', {
    hour: '2-digit',
    minute: '2-digit',
  })

/** Newest first. */
export const newestFirst = (items) =>
  [...items].sort((a, b) => b.createdAt.localeCompare(a.createdAt))
import { test } from 'node:test'
import assert from 'node:assert/strict'
import { withRetry } from '../public/src/retry.js'
import { newestFirst, stateLabel } from '../public/src/format.js'

const noWait = async () => {}

test('a read that fails once is retried and its answer returned', async () => {
  let calls = 0
  const result = await withRetry(
    async () => {
      calls++
      if (calls === 1) throw new Error('network down')
      return 'services'
    },
    [1000, 2000, 4000],
    noWait,
  )
  assert.equal(result, 'services')
  assert.equal(calls, 2)
})

test('the retries wait the delays they are given', async () => {
  const waited = []
  await assert.rejects(
    withRetry(
      async () => {
        throw new Error('network down')
      },
      [1000, 2000, 4000],
      async (ms) => waited.push(ms),
    ),
    /network down/,
  )
  assert.deepEqual(waited, [1000, 2000, 4000])
})

test('states read the way the team names them', () => {
  assert.equal(stateLabel('degraded'), 'Degraded')
})

test('notifications are listed newest first', () => {
  const sorted = newestFirst([
    { id: 'old', createdAt: '2026-11-01T08:00:00.000Z' },
    { id: 'new', createdAt: '2026-11-02T08:00:00.000Z' },
  ])
  assert.deepEqual(
    sorted.map((n) => n.id),
    ['new', 'old'],
  )
})
[
  {
    "id": "api",
    "name": "Public API",
    "state": "degraded",
    "checkedAt": "2026-11-02T08:00:00.000Z"
  },
  {
    "id": "billing",
    "name": "Billing",
    "state": "operational",
    "checkedAt": "2026-11-02T08:00:00.000Z"
  },
  {
    "id": "search",
    "name": "Search",
    "state": "operational",
    "checkedAt": "2026-11-02T08:00:00.000Z"
  },
  {
    "id": "email",
    "name": "Email delivery",
    "state": "outage",
    "checkedAt": "2026-11-02T08:00:00.000Z"
  },
  {
    "id": "storage",
    "name": "File storage",
    "state": "operational",
    "checkedAt": "2026-11-02T08:00:00.000Z"
  }
]
